			left = maxLeft
		}
	} else {
		if left < 1 {
			left = 1
		}
		if left >= available {
			left = available / 2
		}
	}

	right = available - left
	if right < 1 {
		right = 1
		left = available - right
	}
	return left, right
}

func hostOrDefault(host string) string {
	if host == "" {
		return "127.0.0.1"
	}
	return host
}

